"Swapped 50 {0} for {1} {2}":["50 {0} échangés contre {1} {2}","50 {0} cambiados por {1} {2}","50 {0} gegen {1} {2} getauscht","50 {0} scambiati con {1} {2}","50 {0} trocados por {1} {2}"],
